def triage(notes):
    """notes: list[dict]，每个 dict 含 title/year/cites_per_year/has_code/gain"""
    def key(n):
        return (
            -int(bool(n["has_code"])),
            -n["gain"],
            -n["cites_per_year"],
            -n["year"],
        )
    return [n["title"] for n in sorted(notes, key=key)]

