def rank_papers(papers, now_year):
    """papers: list[dict]，每个 dict 含 title/year/cites"""
    def score(p):
        age = max(1, now_year - p["year"] + 1)
        return p["cites"] / age
    return [p["title"] for p in sorted(papers, key=score, reverse=True)]

