import torch


def causal_mask(scores):
    """scores: (B, H, S, S)；返回同形状张量，未来位置为 -inf"""
    seq = scores.size(-1)
    mask = torch.triu(torch.ones(seq, seq, dtype=torch.bool, device=scores.device), diagonal=1)
    return scores.masked_fill(mask, float("-inf"))

import statistics


def summarize_runs(runs, baseline):
    """返回 {'mean':..,'std':..,'n':..,'significant':bool}"""
    mean = statistics.fmean(runs)
    std = statistics.pstdev(runs) if len(runs) > 1 else 0.0
    return {
        "mean": mean,
        "std": std,
        "n": len(runs),
        "significant": abs(mean - baseline) > 2 * std,
    }


if __name__ == "__main__":
    print(summarize_runs([0.9512, 0.9498, 0.9531], 0.9420))

