import torch
import torch.nn as nn


def inspect(model, input_shape):
    """打印每层输出形状与参数量，用于把代码与论文结构对齐"""
    shapes = {}
    hooks = []
    for name, module in model.named_modules():
        if len(list(module.children())) > 0:
            continue

        def make_hook(n):
            def hook(mod, inp, out):
                shapes[n] = tuple(out.shape)
            return hook

        hooks.append(module.register_forward_hook(make_hook(name)))
    model.eval()
    with torch.no_grad():
        model(torch.randn(*input_shape))
    for h in hooks:
        h.remove()
    total = sum(p.numel() for p in model.parameters())
    for name, shape in shapes.items():
        n = sum(p.numel() for p in dict(model.named_modules())[name].parameters())
        print(f"{name:22s} out={str(shape):20s} params={n}")
    print("total params", total)


if __name__ == "__main__":
    net = nn.Sequential(nn.Conv2d(3, 16, 3, padding=1), nn.ReLU(),
                        nn.MaxPool2d(2), nn.Conv2d(16, 32, 3, padding=1), nn.ReLU())
    inspect(net, (1, 3, 32, 32))

