    """返回参数量（整数）"""
    pass

quiz.solution:
def count_params(module, trainable_only=False):
    """返回参数量（整数）"""
    params = module.parameters()
    if trainable_only:
        params = (p for p in params if p.requires_grad)
    return sum(p.numel() for p in params)

