import statistics


def run_one(config, seed):
    """占位：真实场景里这里调用训练脚本并返回验证指标"""
    base = 0.80 if config["use_resample"] else 0.782
    noise = ((seed * 37) % 11 - 5) / 1000.0
    return base + noise


def ablate(configs, seeds=(0, 1, 2)):
    results = {}
    for name, cfg in configs.items():
        scores = [run_one(cfg, s) for s in seeds]
        results[name] = {
            "mean": statistics.fmean(scores),
            "std": statistics.pstdev(scores),
            "n": len(scores),
        }
    return results


if __name__ == "__main__":
    cfgs = {
        "baseline": {"use_resample": False},
        "resample": {"use_resample": True},
    }
    out = ablate(cfgs)
    b, r = out["baseline"], out["resample"]
    delta = r["mean"] - b["mean"]
    for k, v in out.items():
        print(f"{k:9s} mean={v['mean']:.4f} std={v['std']:.4f} n={v['n']}")
    print(f"delta={delta:+.4f} significant={abs(delta) > 2 * max(b['std'], r['std'])}")

