def make_table(rows):
    """返回 Markdown 表格字符串（含表头与分隔行）"""
    lines = ["| Method | Metric | Std |", "| --- | --- | --- |"]
    for r in rows:
        name = r["method"] + ("*" if r.get("ours") else "")
        metric = f"{r['metric']:.2f}"
        if r.get("ours"):
            metric = f"**{metric}**"
        lines.append(f"| {name} | {metric} | {r['std']:.2f} |")
    return "\n".join(lines)


if __name__ == "__main__":
    print(make_table([
        {"method": "Baseline", "metric": 24.8, "std": 0.2, "ours": False},
        {"method": "Ours", "metric": 26.4, "std": 0.1, "ours": True},
    ]))
